def parse_range(header, size):
    if size <= 0:
        return None

    if not header:
        return None

    header = header.strip()
    if not header.startswith("bytes="):
        return None

    spec = header[len("bytes="):]
    ranges = []

    for part in spec.split(","):
        part = part.strip()
        if not part:
            continue

        # Suffix range: bytes=-500
        if part.startswith("-"):
            try:
                length = int(part[1:])
            except ValueError:
                continue
            if length <= 0:
                continue
            if length >= size:
                start, end = 0, size - 1
            else:
                start, end = size - length, size - 1
            ranges.append((start, end))
            continue

        # Normal range: bytes=start-end or bytes=start-
        if "-" not in part:
            continue

        left, right = part.split("-", 1)

        try:
            start = int(left)
        except ValueError:
            continue

        if right.strip() == "":
            # Open-ended range: bytes=500-
            if start >= size:
                continue
            end = size - 1
        else:
            try:
                end = int(right.strip())
            except ValueError:
                continue
            if end >= size:
                end = size - 1
            if start > end:
                continue

        if start < 0 or start >= size:
            continue

        ranges.append((start, end))

    if not ranges:
        return None

    return ranges
