from collections import OrderedDict


class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.key_to_val = {}
        self.key_to_freq = {}
        self.freq_to_keys = OrderedDict()
        self.min_freq = 0

    def get(self, key):
        if key not in self.key_to_val:
            return -1
        self._update(key)
        return self.key_to_val[key]

    def put(self, key, value):
        if self.capacity <= 0:
            return
        if key in self.key_to_val:
            self.key_to_val[key] = value
            self._update(key)
        else:
            if len(self.key_to_val) >= self.capacity:
                old_key, _ = self.freq_to_keys.popitem(last=False)
                del self.freq_to_keys[old_key][old_key]
                del self.key_to_val[old_key]
                del self.key_to_freq[old_key]
            self.key_to_val[key] = value
            self.key_to_freq[key] = 1
            bucket = self.freq_to_keys.get(1, OrderedDict())
            bucket[key] = key
            self.freq_to_keys[1] = bucket
            self.min_freq = 1

    def _update(self, key):
        freq = self.key_to_freq[key]
        del self.freq_to_keys[freq][key]
        if not self.freq_to_keys[freq]:
            del self.freq_to_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1
        self.key_to_freq[key] = freq + 1
        bucket = self.freq_to_keys.get(freq + 1, OrderedDict())
        bucket[key] = key
        self.freq_to_keys[freq + 1] = bucket
