import re


def parse_duration(s):
    if not isinstance(s, str):
        raise ValueError("invalid duration")
    s = s.strip()

    sign = 1
    if s.startswith('-'):
        sign = -1
        s = s[1:]
    elif s.startswith('+'):
        s = s[1:]

    pattern = re.compile(
        r'^P'
        r'(?:(\d+)Y)?'
        r'(?:(\d+)M)?'
        r'(?:(\d+)D)?'
        r'(T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+(?:\.\d+)?)?)?)?'
        r'$'
    )

    m = pattern.match(s)
    if not m:
        raise ValueError(f"invalid duration: {s!r}")

    y, mo, d, h, mi, sec, t = m.groups()

    if not any(v is not None for v in (y, mo, d, h, mi, sec)):
        raise ValueError(f"invalid duration: {s!r}")

    if t is not None and not any(v is not None for v in (h, mi, sec)):
        raise ValueError(f"invalid duration: {s!r}")

    total = 0.0
    if y:
        total += int(y) * 365 * 24 * 3600
    if mo:
        total += int(mo) * 30 * 24 * 3600
    if d:
        total += int(d) * 24 * 3600
    if h:
        total += int(h) * 3600
    if mi:
        total += int(mi) * 60
    if sec:
        total += float(sec)

    return sign * total
