def wildcard_match(pattern, s):
    m, n = len(pattern), len(s)
    # dp[j] = does s[0..j) match pattern[0..i) for the current i
    dp = [False] * (n + 1)
    dp[0] = True  # empty pattern matches empty string
    for i in range(1, m + 1):
        c = pattern[i - 1]
        new_dp = [False] * (n + 1)
        if c == '*':
            new_dp[0] = dp[0]
        for j in range(1, n + 1):
            if c == '*':
                new_dp[j] = dp[j] or new_dp[j - 1]
            elif c == '?' or c == s[j - 1]:
                new_dp[j] = dp[j - 1]
        dp = new_dp
    return dp[n]
```

