def to_base(n, alphabet):
    if not alphabet:
        raise ValueError("alphabet must be non-empty")
    if n == 0:
        return alphabet[0]
    negative = n < 0
    n = abs(n)
    base = len(alphabet)
    digits = []
    while n > 0:
        digits.append(alphabet[n % base])
        n //= base
    if negative:
        digits.append('-')
    return ''.join(reversed(digits))


def from_base(s, alphabet):
    if not s:
        raise ValueError("string must be non-empty")
    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
    if not s:
        raise ValueError("string must be non-empty")
    index = {ch: i for i, ch in enumerate(alphabet)}
    value = 0
    for ch in s:
        if ch not in index:
            raise ValueError("character not in alphabet")
        value = value * len(alphabet) + index[ch]
    return -value if negative else value
