import heapq


def merge_sorted(iterables):
    heap = []
    for i, it in enumerate(iterables):
        try:
            first = next(it)
        except StopIteration:
            continue
        # (value, source_index, iterator) — source_index is a unique
        # tiebreaker that guarantees equal values come out in source order.
        heap.append((first, i, it))
    heapq.heapify(heap)

    while heap:
        value, _, it = heapq.heappop(heap)
        yield value
        try:
            nxt = next(it)
        except StopIteration:
            pass
        else:
            heapq.heappush(heap, (nxt, it))
