import heapq

def topo_lex(graph):
    nodes = set(graph.keys())
    for v in graph.values():
        nodes.update(v)

    indeg = {v: 0 for v in nodes}
    for u, succ in graph.items():
        for v in succ:
            indeg[v] += 1

    heap = [u for u in nodes if indeg[u] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in graph.get(u, []):
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)

    return result if len(result) == len(nodes) else None
