function pLimit(concurrency) {
  if (!(concurrency > 0)) {
    throw new TypeError('Expected concurrency to be a number greater than 0');
  }

  let active = 0;
  let queue = [];
  let running = false;

  function run(next) {
    return new Promise((resolve, reject) => {
      queue.push({ next, resolve, reject });
      pump();
    });
  }

  function pump() {
    if (running) return;
    while (active < concurrency && queue.length) {
      const { next, resolve, reject } = queue.shift();
      active += 1;
      running = true;
      Promise.resolve()
        .then(next)
        .then(
          resolve,
          (err) => {
            active -= 1;
            running = false;
            reject(err);
            pump();
          }
        )
        .then(() => {
          active -= 1;
          running = false;
          pump();
        });
    }
  }

  return run;
}

module.exports = pLimit;
