class Emitter {
  constructor() {
    this._listeners = new Map();
    this._once = new Map();
  }

  on(event, fn) {
    if (!this._listeners.has(event)) this._listeners.set(event, new Set());
    this._listeners.get(event).add(fn);
    return () => this.off(event, fn);
  }

  once(event, fn) {
    if (!this._once.has(event)) this._once.set(event, new Set());
    this._once.get(event).add(fn);
  }

  off(event, fn) {
    const listeners = this._listeners.get(event);
    if (listeners) listeners.delete(fn);
    const once = this._once.get(event);
    if (once) once.delete(fn);
  }

  emit(event, ...args) {
    const listeners = this._listeners.get(event) || new Set();
    const once = this._once.get(event) || new Set();

    const snapshot = [...listeners, ...once];

    let count = 0;
    let firstError;

    for (const fn of snapshot) {
      const isOnce = once.has(fn);
      if (!listeners.has(fn) && !isOnce) continue;
      try {
        if (isOnce) once.delete(fn);
        fn(...args);
        count++;
      } catch (err) {
        if (firstError === undefined) firstError = err;
      }
    }

    if (firstError !== undefined) {
      throw firstError;
    }

    return count;
  }
}

module.exports = Emitter;
