function deepEqual(a, b, cache = new WeakMap()) {
  // SameValueZero: NaN === NaN, +0 === -0, and ordinary equality.
  if (a === b || (a !== a && b !== b)) return true;

  // Cycle detection: an object already seen must map to the same reference.
  if (cache.has(a)) return cache.get(a) === b;
  cache.set(a, b);

  // null/undefined have no usable constructor.
  if (a === null || b === null) return false;

  // Date: compare by time value.
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // RegExp: compare by source and flags.
  if (a instanceof RegExp && b instanceof RegExp) {
    return a.source === b.source && a.flags === b.flags;
  }

  // Map: compare by contents irrespective of insertion order.
  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    const seen = new WeakSet();
    for (const [k, v] of a) {
      let matched = false;
      for (const [k2, v2] of b) {
        if (seen.has(k2)) continue;
        if (deepEqual(k, k2, cache) && deepEqual(v, v2, cache)) {
          seen.add(k2);
          matched = true;
          break;
        }
      }
      if (!matched) return false;
    }
    return true;
  }

  // Set: compare by contents irrespective of insertion order.
  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    const seen = new WeakSet();
    for (const v of a) {
      let matched = false;
      for (const w of b) {
        if (seen.has(w)) continue;
        if (deepEqual(v, w, cache)) {
          seen.add(w);
          matched = true;
          break;
        }
      }
      if (!matched) return false;
    }
    return true;
  }

  // Array: compare element by element (order matters).
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i], cache)) return false;
    }
    return true;
  }

  // Plain object: compare by own enumerable keys.
  if (a.constructor === Object && b.constructor === Object) {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
      if (!deepEqual(a[key], b[key], cache)) return false;
    }
    return true;
  }

