function sqlTag(strings, ...subs) {
  let text = '';
  const values = [];
  let counter = 0;

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];
    const sub = subs[i];

    if (sub && typeof sub === 'object' && SQL in sub) {
      // nested sqlTag result: inline its text, renumber its placeholders,
      // merge its values into the current sequence
      const start = counter;
      const n = sub.values.length;
      text += sub.text.replace(/\$(\d+)/g, (_, p) => '$' + (start + Number(p)));
      for (let k = 0; k < n; k++) values.push(sub.values[k]);
      counter += n;
    } else if (Array.isArray(sub)) {
      // parenthesised comma-separated list of placeholders
      for (let j = 0; j < sub.length; j++) {
        counter++;
        const placeholder = '$' + counter;
        text += '(' + placeholder;
        if (j < sub.length - 1) {
          text += ', ' + placeholder;
        }
        text += ')';
        values.push(sub[j]);
      }
    } else {
      counter++;
      text += '$' + counter;
      values.push(sub);
    }
  }

