    if (inReducer) {
      throw new Error('Cannot dispatch from within a reducer');
    }
    inReducer = true;
    try {
      state = reducer(state, action);
    } finally {
      inReducer = false;
    }
    const snapshot = listeners.slice();
    for (const listener of snapshot) {
      listener();
    }
    return state;
  }

  return { getState, dispatch, subscribe };
}

