          if (state[dep] === 'pending') {
            state[dep] = 'running';
            runTask(dep);
          }
        }
      },
      (err) => {
        errors[name] = err;
        state[name] = 'failed';
        settled++;
        if (!rejected) {
          rejected = true;
          reject(err);
        }
        for (const dep of dependents[name]) failDependent(dep);
      }
    );
  }

  function failDependent(name) {
    for (const dep of dependents[name]) {
      if (state[dep] === 'pending') {
        state[dep] = 'failed';
        errors[dep] = errors[name];
        settled++;
        failDependent(dep);
      }
    }
  }

